let csrf='';
const $=s=>document.querySelector(s);
const $$=s=>[...document.querySelectorAll(s)];
const cache={products:[],orders:[],customers:[],reviews:[],inventory:[],audit:[],returns:[],analytics:null,sellers:[],payouts:[],coupons:[],questions:[],support:[],risk:[],metrics:{}};
const esc=v=>String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const money=(value,currency)=>WorkspaceMoney.format(value,currency);
const date=v=>v?new Date(v).toLocaleString(undefined,{dateStyle:'medium',timeStyle:'short'}):'—';
const initials=v=>String(v||'NA').split('@')[0].split(/[._-]/).map(x=>x[0]).join('').slice(0,2).toUpperCase();
function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.remove('hidden');clearTimeout(toast.t);toast.t=setTimeout(()=>t.classList.add('hidden'),2800)}
function badgeClass(s){s=String(s||'').toLowerCase();if(['paid','delivered','approved','active','answered'].includes(s))return'green';if(['processing','packed','shipped','in_transit','out_for_delivery','available','open'].includes(s))return'blue';if(['pending','placed','requested','received','unpaid','cod'].includes(s))return'amber';if(['cancelled','refunded','rejected','failed','hidden','exception'].includes(s))return'red';return'blue'}
async function api(url,opt={}){const headers={...(opt.headers||{})};if(opt.body&&!(opt.body instanceof FormData)&&!headers['content-type'])headers['content-type']='application/json';if(csrf)headers['x-csrf-token']=csrf;const r=await fetch(url,{...opt,headers});const j=await r.json().catch(()=>({}));return{r,j}}
function view(id){$$('.view').forEach(x=>x.classList.toggle('active',x.id===id));$$('[data-view]').forEach(x=>x.classList.toggle('active',x.dataset.view===id));const meta={overview:['Your store, at a glance.','The numbers, the orders and the moments that matter.'],orders:['Orders workspace','Process payments, fulfilment and customer order issues.'],products:['Product studio','Build and maintain the catalogue with richer controls.'],customers:['Customer intelligence','Understand buyer value and activity.'],inventory:['Inventory control','Keep stock accurate and catch low-stock risks early.'],reviews:['Review moderation','Keep customer feedback healthy and relevant.'],returns:['Returns & refunds','Resolve return requests and align refund states.'],sellers:['Seller control','Run marketplace approvals and seller operations.'],payouts:['Payout ledger','Track seller settlement states.'],promotions:['Promotion center','Create and monitor coupon campaigns.'],questions:['Product Q&A','Answer buyer questions from one queue.'],analytics:['Business analytics','Explore revenue, orders, AOV and category performance.'],audit:['Audit & operational history','Review what changed and when.'],settings:['Store control center','Review key configuration and launch-readiness notes.']}[id]||[];$('#pageTitle').textContent=meta[0]||'NovaCart Admin';$('#pageSub').textContent=meta[1]||'';location.hash=id;if(innerWidth<821)$('#sidebar').classList.remove('open');}
function openModal(html){$('#modal').innerHTML=html;$('#modalBackdrop').classList.add('open')}
function closeModal(){$('#modalBackdrop').classList.remove('open');$('#modal').innerHTML=''}
function openDrawer(html){$('#orderDrawer').innerHTML=html;$('#drawerBackdrop').classList.add('open')}
function closeDrawer(){$('#drawerBackdrop').classList.remove('open');$('#orderDrawer').innerHTML=''}
async function loadAll(){
  try{
  const config=await api('/api/store-config');
  if(!config.r.ok)throw new Error('Store currency is unavailable. Refresh to retry.');
  WorkspaceMoney.setCurrency(config.j.currency);$('#settingsCurrency').textContent=WorkspaceMoney.currency;
  document.querySelectorAll('[data-store-currency]').forEach(el=>el.textContent=WorkspaceMoney.currency);
  $('#couponFixed').placeholder='Fixed off ('+WorkspaceMoney.currency+')';$('#couponMin').placeholder='Minimum subtotal ('+WorkspaceMoney.currency+')';
  const reqs=[fetch('/api/admin/products'),api('/api/admin/orders'),api('/api/admin/customers'),api('/api/admin/reviews'),api('/api/admin/inventory'),api('/api/admin/audit-logs'),api('/api/admin/metrics'),api('/api/admin/returns'),api('/api/admin/analytics?days=30'),api('/api/admin/sellers'),api('/api/admin/payouts'),api('/api/admin/coupons'),api('/api/admin/questions'),api('/api/admin/support-tickets'),api('/api/admin/fraud-events')];
  const out=await Promise.all(reqs);const productData=await out[0].json().catch(()=>({}));const [od,cd,rv,iv,au,mt,rt,an,sl,po,co,qu,sup,rf]=out.slice(1).map(x=>x.j);
  cache.products=productData.products||[];cache.orders=od?.orders||[];cache.customers=cd?.customers||[];cache.reviews=rv?.reviews||[];cache.inventory=iv?.products||[];cache.audit=au?.logs||[];cache.metrics=mt||{};cache.returns=rt?.returns||[];cache.analytics=an||null;cache.sellers=sl?.sellers||[];cache.payouts=po?.payouts||[];cache.coupons=co?.coupons||[];cache.questions=qu?.questions||[];cache.support=sup?.tickets||[];cache.risk=rf?.events||[];
  renderEverything();$('#healthPill').textContent='DATA UPDATED';$('#lastSync').textContent='SYNCED '+new Date().toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'});$('#todayChip').textContent=new Date().toLocaleDateString(undefined,{weekday:'short',month:'short',day:'numeric'});
  }catch(error){toast(error.message||'Could not load dashboard. Refresh to retry.');}
}
function renderEverything(){renderKPIs();renderOverviewChart();renderAttention();renderOrderPulse();renderRecentMini();renderTopProducts();renderOrders();renderProducts();renderCustomers();renderInventory();renderReviews();renderReturns();renderSellers();renderPayouts();renderCoupons();renderQuestions();renderSupport();renderRisk();renderAnalytics();renderAudit();}
function renderKPIs(){const m=cache.metrics;$('#statRevenue').textContent=money(m.revenue);$('#statOrders').textContent=m.orders??cache.orders.length;$('#statCustomers').textContent=m.customers??cache.customers.length;$('#statProducts').textContent=m.products??cache.products.filter(p=>p.active).length;$('#statLowStock').textContent=m.lowStock??cache.inventory.filter(p=>Number(p.stock)<=5).length;$('#reviewQueueBadge').textContent=`${m.pendingReviews??cache.reviews.filter(r=>r.status==='pending').length} PENDING`;$('#sellerBadge').textContent=`${cache.sellers.length} SELLERS`}
function chartHTML(rows,box='overviewChart'){const vals=rows.map(x=>Number(x.revenue||0));const max=Math.max(...vals,1);const low=Math.min(...vals,0),high=Math.max(...vals,0);if(!rows.length){document.getElementById(box).innerHTML='<div class="empty">No revenue data yet.</div>';return{low:0,high:0};}document.getElementById(box).innerHTML=rows.slice(-12).map(x=>{const h=Math.max(7,Math.round(Number(x.revenue||0)/max*185));const d=new Date(x.day);return`<div class="bar-col" title="${esc(d.toLocaleDateString())} — ${money(x.revenue)}"><div class="bar" style="height:${h}px"></div><div class="bar-label">${esc(d.toLocaleDateString(undefined,{month:'short',day:'numeric'}))}</div></div>`}).join('');return{low,high}}
function renderOverviewChart(){if(!cache.analytics)return;const r=chartHTML(cache.analytics.daily||[],'overviewChart');$('#overviewLow').textContent=money(r.low);$('#overviewHigh').textContent=money(r.high)}
function renderAttention(){const m=cache.metrics;const items=[['!','Low stock','Products at or below five units',m.lowStock||0,'inventory'],['★','Review queue','Reviews waiting for moderation',m.pendingReviews||0,'reviews'],['◆','Seller review','Seller profiles requiring attention',cache.sellers.filter(s=>s.status==='pending').length,'sellers'],['↩','Return requests','Open return requests',cache.returns.filter(r=>['requested','approved','received'].includes(r.status)).length,'returns'],['?','Open questions','Buyer questions waiting for answers',cache.questions.filter(q=>q.status==='open').length,'questions']];$('#attentionList').innerHTML=items.map(x=>`<a class="alert" href="#${x[4]}" data-view="${x[4]}" style="text-decoration:none;color:inherit"><div class="alert-icon">${x[0]}</div><div><strong>${esc(x[1])}</strong><span>${esc(x[2])}</span></div><div class="count">${x[3]}</div></a>`).join('')}
function renderOrderPulse(){const statuses=['placed','processing','packed','shipped','delivered','cancelled'];const counts=statuses.map(s=>[s,cache.orders.filter(o=>o.status===s).length]);$('#orderPulse').innerHTML=counts.map(x=>`<div class="summary-mini"><span>${esc(x[0].replace('_',' '))}</span><strong>${x[1]}</strong></div>`).join('')}
function renderRecentMini(){const rows=cache.orders.slice(0,7);$('#recentOrdersMini').innerHTML=rows.length?`<table class="table"><thead><tr><th>Order</th><th>Customer</th><th>Total</th><th>Status</th><th></th></tr></thead><tbody>${rows.map(o=>`<tr><td><strong>${esc(o.id)}</strong><div class="cell-title"><span>${date(o.created_at)}</span></div></td><td>${esc(o.customer_email)}</td><td>${money(o.total,o.currency)}</td><td><span class="badge ${badgeClass(o.status)}">${esc(o.status)}</span></td><td><button class="mini-btn" data-order-detail="${esc(o.id)}">Open</button></td></tr>`).join('')}</tbody></table>`:'<div class="empty">No orders yet.</div>';}
function renderTopProducts(){const list=[...cache.products].sort((a,b)=>Number(b.reviews||0)-Number(a.reviews||0)).slice(0,5);$('#topProductsMini').innerHTML=list.length?list.map((p,i)=>`<div class="alert"><div class="alert-icon">${String(i+1).padStart(2,'0')}</div><div style="min-width:0"><strong style="white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${esc(p.title)}</strong><span>${esc(p.cat||'Other')} · stock ${Number(p.stock||0)} · ${Number(p.reviews||0)} reviews</span></div><div class="count">${money(p.price,p.currency)}</div></div>`).join(''):'<div class="empty">No products yet.</div>'}
function renderOrders(){const q=($('#globalSearch').value||'').toLowerCase();const sf=$('#orderStatusFilter').value;const pf=$('#orderPaymentFilter').value;let rows=cache.orders.filter(o=>`${o.id} ${o.customer_email||''}`.toLowerCase().includes(q));if(sf)rows=rows.filter(o=>o.status===sf);if(pf)rows=rows.filter(o=>o.payment_status===pf);const sums=[['All',rows.length],['Paid',rows.filter(o=>o.payment_status==='paid').length],['Pending',rows.filter(o=>['pending_payment','placed'].includes(o.status)).length],['Shipped',rows.filter(o=>['shipped','delivered'].includes(o.status)).length]];$('#ordersSummary').innerHTML=sums.map(x=>`<div class="summary-mini"><span>${x[0]}</span><strong>${x[1]}</strong></div>`).join('');$('#ordersTable').innerHTML=rows.length?`<table class="table"><thead><tr><th>Order</th><th>Customer</th><th>Items</th><th>Total</th><th>Payment</th><th>Status</th><th>Fulfilment</th><th></th></tr></thead><tbody>${rows.map(o=>`<tr><td><strong>${esc(o.id)}</strong><div class="cell-title"><span>${date(o.created_at)}</span></div></td><td><div class="cell-main"><div class="thumb">${esc(initials(o.customer_email))}</div><div class="cell-title"><strong>${esc(o.customer_name||'Customer')}</strong><span>${esc(o.customer_email)}</span></div></div></td><td>${Number(o.itemCount||0)}</td><td>${money(o.total,o.currency)}</td><td><span class="badge ${badgeClass(o.payment_status)}">${esc(o.payment_status||'—')}</span></td><td><span class="badge ${badgeClass(o.status)}">${esc(o.status)}</span></td><td>${esc(o.courier||'—')}<div class="cell-title"><span>${esc(o.tracking_number||'No tracking')}</span></div></td><td><div class="row-actions"><button class="mini-btn" data-order-detail="${esc(o.id)}">Details</button><button class="mini-btn" data-order-status="${esc(o.id)}">Update</button>${o.payment_method==='cod'&&o.payment_status==='cod'&&o.status==='delivered'?`<button class="mini-btn" data-cod-collect="${esc(o.id)}">Record COD collection</button>`:''}${o.payment_method==='stripe'&&['paid','partially_refunded'].includes(o.payment_status)&&o.status!=='refunded'?`<button class="mini-btn danger" data-refund="${esc(o.id)}">Refund</button>`:''}</div></td></tr>`).join('')}</tbody></table>`:'<div class="empty">No matching orders.</div>';bindOrderButtons()}
function bindOrderButtons(){$$('[data-order-detail]').forEach(b=>b.onclick=()=>openOrder(b.dataset.orderDetail));$$('[data-order-status]').forEach(b=>b.onclick=()=>updateOrderPrompt(b.dataset.orderStatus));$$('[data-refund]').forEach(b=>b.onclick=()=>refundOrder(b.dataset.refund))}
async function openOrder(id){const r=await api(`/api/admin/orders/${encodeURIComponent(id)}`);if(!r.r.ok)return toast(r.j.error||'Could not load order');const o=r.j.order;openDrawer(`<div class="card-head" style="padding:0 0 14px;border:0"><div><div class="eyebrow">Order detail</div><h3 style="margin-top:5px">${esc(o.id)}</h3><p>${date(o.created_at)} · ${esc(o.customer_email)}</p></div><button class="close" data-close-drawer>×</button></div><div class="summary-strip"><div class="summary-mini"><span>Total</span><strong>${money(o.total,o.currency)}</strong></div><div class="summary-mini"><span>Payment</span><strong>${esc(o.payment_status||'')}</strong></div><div class="summary-mini"><span>Status</span><strong>${esc(o.status||'')}</strong></div><div class="summary-mini"><span>Items</span><strong>${Number(o.items?.reduce((s,i)=>s+Number(i.qty||0),0)||0)}</strong></div></div><div class="detail-grid"><div class="detail"><label>Customer</label><strong>${esc(o.customer_name||'Customer')}</strong><span class="muted">${esc(o.customer_email)}</span></div><div class="detail"><label>Phone</label><strong>${esc(o.phone||'—')}</strong></div><div class="detail"><label>Shipping</label><strong>${esc(o.delivery||'standard')}</strong><span class="muted">${esc(o.courier||'—')} ${esc(o.tracking_number||'')}</span></div><div class="detail"><label>Totals</label><strong>Subtotal ${money(o.subtotal,o.currency)} · Shipping ${money(o.shipping,o.currency)} · Tax ${money(o.tax,o.currency)}</strong></div></div><div class="section" style="margin-top:12px"><div class="card-head" style="padding:12px 0;border:0"><div><h3>Items</h3></div></div>${(o.items||[]).map(i=>`<div class="detail" style="margin-bottom:7px"><div class="cell-main"><div class="thumb">N</div><div class="cell-title"><strong>${esc(i.title)}</strong><span>Qty ${Number(i.qty||0)} · ${money(i.unit_price??i.unitPrice,o.currency)}</span></div><strong style="margin-left:auto">${money(Number(i.qty||0)*Number(i.unit_price??i.unitPrice??0),o.currency)}</strong></div></div>`).join('')||'<div class="empty">No line items.</div>'}</div><div class="section"><div class="card-head" style="padding:12px 0;border:0"><div><h3>Status history</h3></div></div><div class="timeline">${(o.statusHistory||[]).map(h=>`<div class="timeline-item"><div class="timeline-dot">•</div><div class="timeline-body"><strong>${esc(h.to_status)}</strong><span>${date(h.created_at)} · ${esc(h.changed_by_email||'system')} · ${esc(h.note||'')}</span></div></div>`).join('')||'<div class="empty">No history yet.</div>'}</div></div><div class="section"><div class="card-head" style="padding:12px 0;border:0"><div><h3>Refunds</h3></div><span class="badge ${o.refunds?.length?'amber':'blue'}">${o.refunds?.length||0}</span></div>${(o.refunds||[]).map(x=>`<div class="detail" style="margin-bottom:7px"><label>${date(x.created_at)}</label><strong>${money(x.amount,x.currency||o.currency)} · ${esc(x.status)}</strong><span class="muted">${esc(x.reason||'')}</span></div>`).join('')||'<div class="empty">No refunds.</div>'}</div><div class="section"><button class="btn primary" data-order-status="${esc(o.id)}">Update order</button> <button class="btn" data-shipment="${esc(o.id)}">Add shipment event</button>${o.payment_method==='cod'&&o.payment_status==='cod'&&o.status==='delivered'?`<button class="mini-btn" data-cod-collect="${esc(o.id)}">Record COD collection</button>`:''}${o.payment_method==='stripe'&&['paid','partially_refunded'].includes(o.payment_status)&&o.status!=='refunded'?` <button class="btn danger" data-refund="${esc(o.id)}">Refund</button>`:''}</div>`);$('[data-close-drawer]').onclick=closeDrawer;$$('[data-order-status]').forEach(b=>b.onclick=()=>updateOrderPrompt(b.dataset.orderStatus));$$('[data-refund]').forEach(b=>b.onclick=()=>refundOrder(b.dataset.refund));$('[data-shipment]')?.addEventListener('click',()=>shipmentPrompt(id))}
async function updateOrderPrompt(id){const status=prompt('New order status: placed / processing / packed / shipped / delivered / cancelled',cache.orders.find(o=>o.id===id)?.status||'processing');if(status===null)return;const courier=prompt('Courier (optional):',cache.orders.find(o=>o.id===id)?.courier||'')??'';const tracking=prompt('Tracking number (optional):',cache.orders.find(o=>o.id===id)?.tracking_number||'')??'';const note=prompt('Internal/customer note (optional):','Updated by admin')??'';const r=await api(`/api/admin/orders/${encodeURIComponent(id)}`,{method:'PATCH',body:JSON.stringify({status:status.trim().toLowerCase(),courier,trackingNumber:tracking,note})});if(!r.r.ok)return toast(r.j.error||'Order update failed');toast('Order updated');closeDrawer();loadAll()}
async function refundOrder(id){
 try{
  const existing=await api(`/api/admin/orders/${encodeURIComponent(id)}/refunds`);if(!existing.r.ok)return toast(existing.j.error||'Could not check refunds');
  const pending=(existing.j.refunds||[]).find(x=>x.request_key&&!x.stripe_refund_id&&['sending','unknown'].includes(x.submission_state));
  let body,key;
  if(pending){if(!confirm('An earlier refund has an unconfirmed result. Retry verification of that same request?'))return;body=pending.request_payload;key=pending.request_key;}
  else{
   const amount=prompt('Refund amount ('+(WorkspaceMoney.code(cache.orders.find(o=>o.id===id)?.currency)||WorkspaceMoney.currency)+'). Leave blank for the remaining refundable amount:','');if(amount===null)return;
   const parsed=amount.trim()?Number(amount):null;
   if(parsed!==null&&(!Number.isFinite(parsed)||parsed<=0||Math.round(parsed*100)/100!==parsed))return toast('Enter a positive amount with at most two decimal places.');
   const reason=prompt('Refund reason:','Admin refund');if(reason===null)return;
   body={reason:reason||'Admin refund'};if(parsed!==null)body.amount=parsed;key=crypto.randomUUID();
  }
  const result=await api(`/api/admin/orders/${encodeURIComponent(id)}/refund`,{method:'POST',headers:{'idempotency-key':key},body:JSON.stringify(body)});
  if(!result.r.ok)return toast(result.j.error||'Refund request failed');toast(`Refund ${result.j.refundId} · ${result.j.status}`);closeDrawer();loadAll();
 }catch{toast('Connection lost. Reopen Refund to verify the existing request before trying again.');}
}
async function shipmentPrompt(id){const status=prompt('Shipment event: label_created / in_transit / out_for_delivery / delivered / exception','in_transit');if(status===null)return;const location=prompt('Location (optional):','')||'';const note=prompt('Shipment note (optional):','')||'';const r=await api(`/api/admin/orders/${encodeURIComponent(id)}/shipment-events`,{method:'POST',body:JSON.stringify({status,location,note})});if(!r.r.ok)return toast(r.j.error||'Shipment event failed');toast('Shipment event added');openOrder(id)}
function renderProducts(){const q=($('#productSearch').value||$('#globalSearch').value||'').toLowerCase();const rows=cache.products.filter(p=>`${p.title} ${p.sku||''} ${p.cat||''}`.toLowerCase().includes(q));$('#productsTable').innerHTML=rows.length?`<table class="table"><thead><tr><th>Product</th><th>SKU</th><th>Category</th><th>Price</th><th>Stock</th><th>Rating</th><th>Status</th><th></th></tr></thead><tbody>${rows.map(p=>`<tr><td><div class="cell-main"><div class="thumb">${p.image?`<img src="${esc(p.image)}" alt="">`:'N'}</div><div class="cell-title"><strong>${esc(p.title)}</strong><span>${esc(p.badge||'')} · ${esc(p.id)}</span></div></div></td><td>${esc(p.sku||'—')}</td><td>${esc(p.cat||'Other')}</td><td>${money(p.price,p.currency)}${p.oldPrice?`<div class="cell-title"><span>was ${money(p.oldPrice,p.currency)}</span></div>`:''}</td><td><span class="badge ${Number(p.stock)<=0?'red':Number(p.stock)<=5?'amber':'green'}">${Number(p.stock)}</span></td><td>${Number(p.rating||0).toFixed(1)} · ${Number(p.reviews||0)}</td><td><span class="badge ${p.active?'green':'red'}">${p.active?'Live':'Archived'}</span></td><td><div class="row-actions"><button class="mini-btn" data-edit-product="${esc(p.id)}">Edit</button><button class="mini-btn" data-product-assets="${esc(p.id)}">Variants/media</button><button class="mini-btn danger" data-archive-product="${esc(p.id)}">Archive</button></div></td></tr>`).join('')}</tbody></table>`:'<div class="empty">No matching products.</div>';$$('[data-edit-product]').forEach(b=>b.onclick=()=>productEditor(b.dataset.editProduct));$$('[data-product-assets]').forEach(b=>b.onclick=()=>assetManager(b.dataset.productAssets));$$('[data-archive-product]').forEach(b=>b.onclick=()=>archiveProduct(b.dataset.archiveProduct))}
function productEditor(id=null){const p=id?cache.products.find(x=>x.id===id):{};openModal(`<div class="modal-head"><div><div class="eyebrow">${id?'Edit catalogue item':'New catalogue item'}</div><h3>${id?esc(p.title):'Create product'}</h3></div><button class="close" data-close-modal>×</button></div><div class="modal-body"><p>Prices in ${esc(p.currency||WorkspaceMoney.currency)}</p><div class="form-grid"><input id="mTitle" class="input wide" placeholder="Product title" value="${esc(p.title||'')}"><input id="mSku" class="input" placeholder="SKU" value="${esc(p.sku||'')}"><input id="mCat" class="input" placeholder="Category" value="${esc(p.cat||'Other')}"><input id="mPrice" class="input" type="number" step="0.01" placeholder="Price" value="${p.price??''}"><input id="mOld" class="input" type="number" step="0.01" placeholder="Compare-at price" value="${p.oldPrice??''}"><input id="mStock" class="input" type="number" placeholder="Stock" value="${p.stock??0}"><input id="mCost" class="input" type="number" step="0.01" placeholder="Cost price" value="${p.cost_price??0}"><input id="mBadge" class="input" placeholder="Badge" value="${esc(p.badge||'')}"><input id="mImage" class="input wide" placeholder="Primary image URL" value="${esc(p.image||'')}"><input id="mSeoTitle" class="input wide" placeholder="SEO title" value="${esc(p.seo_title||'')}"><textarea id="mSeoDesc" class="textarea wide" placeholder="SEO description">${esc(p.seo_description||'')}</textarea><textarea id="mDesc" class="textarea wide" placeholder="Product description">${esc(p.description||'')}</textarea></div><div style="display:flex;justify-content:flex-end;gap:7px;margin-top:14px"><button class="btn" data-close-modal>Cancel</button><button id="saveProduct" class="btn primary">${id?'Save changes':'Publish product'}</button></div></div>`);$$('[data-close-modal]').forEach(b=>b.onclick=closeModal);$('#saveProduct').onclick=async()=>{const payload={title:$('#mTitle').value.trim(),sku:$('#mSku').value.trim(),cat:$('#mCat').value.trim()||'Other',price:Number($('#mPrice').value),oldPrice:$('#mOld').value===''?null:Number($('#mOld').value),stock:Number($('#mStock').value||0),costPrice:Number($('#mCost').value||0),badge:$('#mBadge').value.trim(),image:$('#mImage').value.trim(),description:$('#mDesc').value.trim(),seoTitle:$('#mSeoTitle').value.trim(),seoDescription:$('#mSeoDesc').value.trim()};if(!payload.title||!Number.isFinite(payload.price)||!payload.image)return toast('Title, valid price and image are required.');const url=id?`/api/admin/products/${encodeURIComponent(id)}`:'/api/admin/products';const r=await api(url,{method:id?'PATCH':'POST',body:JSON.stringify(payload)});if(!r.r.ok)return toast(r.j.error||'Product save failed');closeModal();toast(id?'Product updated':'Product published');loadAll()}}
