function renderPayouts(){
  const rows=cache.payouts,pm=p=>v=>money(v,p.currency);
  $('#payoutTable').innerHTML=rows.length?`<table class="table"><thead><tr><th>Store / period</th><th>Earnings</th><th>Refund deduction</th><th>Net transfer</th><th>Status</th><th>Actions</th></tr></thead><tbody>${rows.map(p=>{const m=pm(p),closed=['paid','settled'].includes(p.status);return `<tr><td>${esc(p.store_name)}<br><small>${esc(String(p.period_start).slice(0,10))} → ${esc(String(p.period_end).slice(0,10))}</small></td><td>${esc(m(Number(p.gross_amount)-Number(p.commission_amount)))}</td><td>${esc(m(p.refund_amount))}</td><td><strong>${esc(m(p.net_amount))}</strong></td><td><span class="badge ${badgeClass(p.status)}">${esc(p.status==='settled'?'settled by offsets':p.status)}</span></td><td>${p.ledger_version===1?`<button class="btn" type="button" data-payout-reconcile="${esc(p.id)}">Reconcile refunds</button>`:''}${closed?'':`<select aria-label="Payout status for ${esc(p.store_name)}" class="select" style="width:120px;padding:7px" data-payout-status="${esc(p.id)}"><option value="pending" disabled>pending</option><option value="available">available</option><option value="paid">paid</option><option value="failed">failed</option></select>`}</td></tr>`}).join('')}</tbody></table>`:'<div class="empty">No payout rows.</div>';
  $$('[data-payout-reconcile]').forEach(button=>button.onclick=async()=>{
    button.disabled=true;
    try{const r=await api('/api/admin/payouts/'+encodeURIComponent(button.dataset.payoutReconcile)+'/reconcile',{method:'POST',body:'{}'});if(!r.r.ok)throw new Error(r.j.error||'Reconciliation failed.');const p=cache.payouts.find(p=>p.id===button.dataset.payoutReconcile),m=pm(p),b=r.j.balance;await loadAll();openModal(`<div class="modal-head"><h3>Refund reconciliation</h3></div><div class="section-body">${r.j.needsReview?`<p role="alert"><strong>Transfer blocked:</strong> ${esc(r.j.note)} Any refund reservations have been released for other payouts.</p>`:''}<p>Net transfer for this payout: <strong>${esc(m(r.j.net))}</strong></p><p>Refund deduction: ${esc(m(r.j.refundDeduction))}</p><p>Seller balance carried forward: ${esc(m(b.carryForward))}</p><p>Paid records stay unchanged. Review the updated net amount before recording a completed transfer.</p><div style="max-height:35vh;overflow:auto">${b.adjustments.map(a=>`<p><b>${esc(a.orderId)}</b><br>Recovery: ${esc(m(a.debit))} · Recovered: ${esc(m(a.recovered))} · Reserved: ${esc(m(a.reserved))} · Remaining: ${esc(m(a.remaining))}</p>`).join('')||'<p>No refund adjustments.</p>'}</div><button class="btn" type="button" id="closePayoutReview">Close</button></div>`);$('#closePayoutReview').onclick=closeModal;}catch(e){toast(e.message);}finally{button.disabled=false;}
  });
  $$('[data-payout-status]').forEach(el=>{
    const p=cache.payouts.find(x=>x.id===el.dataset.payoutStatus);el.value=p.status;
    el.onchange=async()=>{let transferReference='';if(el.value==='paid'){transferReference=prompt('Completed transfer reference for '+pm(p)(p.net_amount)+' (this screen does not send money):','')||'';if(!transferReference.trim()){el.value=p.status;return;}}
      el.disabled=true;try{const r=await api(`/api/admin/payouts/${encodeURIComponent(el.dataset.payoutStatus)}`,{method:'PATCH',body:JSON.stringify({status:el.value,transferReference})});if(!r.r.ok)throw new Error(r.j.error||'Payout update failed');toast('Payout updated');await loadAll();}catch(e){el.value=p.status;toast(e.message);}finally{el.disabled=false;}
    };
  });
}

