let adminAuthMethod='totp',emailCodeSent=false,resendAvailableAt=0,loginBusy=false;
function loginControls(){
 $('#adminOtp').classList.toggle('hidden',adminAuthMethod==='none'||adminAuthMethod==='email'&&!emailCodeSent);
 $('#adminOtp').placeholder=adminAuthMethod==='email'?'6-digit email code':'Authenticator code';
 $('#loginBtn').textContent=loginBusy?'Please wait…':adminAuthMethod==='email'?(emailCodeSent?'Verify & sign in →':'Send email code →'):'Sign in →';$('#loginBtn').disabled=loginBusy;
 $('#resendOtpBtn').classList.toggle('hidden',adminAuthMethod!=='email'||!emailCodeSent);$('#resendOtpBtn').disabled=loginBusy||Date.now()<resendAvailableAt;
}
async function adminLogin(resend=false){if(loginBusy)return;if(emailCodeSent&&!resend&&!/^\d{6}$/.test($('#adminOtp').value.trim())){$('#loginStatus').textContent='Enter the 6-digit email code.';return;}loginBusy=true;loginControls();
 try{const r=await api('/api/admin/login',{method:'POST',body:JSON.stringify({email:$('#adminEmail').value.trim(),password:$('#adminPassword').value,otp:resend?'':$('#adminOtp').value.trim(),resend})});if(!r.r.ok)throw Error(r.j.error||'Login failed');
 if(r.j.requiresOtp){adminAuthMethod='email';emailCodeSent=true;$('#adminOtp').value='';resendAvailableAt=Date.now()+60000;setTimeout(loginControls,60100);$('#loginStatus').className='login-status success';$('#loginStatus').textContent='Code sent to '+r.j.destination+'. Check inbox/spam. Valid for 10 minutes; resend after 60 seconds.';loginControls();$('#adminOtp').focus();return;}
 csrf=r.j.csrfToken;$('#adminPassword').value='';$('#adminOtp').value='';emailCodeSent=false;$('#auth').classList.add('hidden');$('#app').classList.remove('hidden');$('#app').classList.add('show');$('#settingsBase').textContent=location.host;loadAll();view(location.hash.slice(1)||'overview');
 }catch(e){$('#loginStatus').className='login-status';$('#loginStatus').textContent=e.message||'Connection failed. Retry.';}finally{loginBusy=false;loginControls();}}
$('#loginBtn').onclick=()=>adminLogin();$('#resendOtpBtn').onclick=()=>adminLogin(true);
for(const id of ['adminEmail','adminPassword'])$('#'+id).addEventListener('input',()=>{emailCodeSent=false;$('#adminOtp').value='';$('#loginStatus').textContent='';loginControls();});
for(const id of ['adminEmail','adminPassword','adminOtp'])$('#'+id).addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();$('#loginBtn').click();}});
async function loadAdminAuthMethod(){try{const r=await api('/api/admin/auth-method');if(!r.r.ok)throw Error();adminAuthMethod=r.j.method;loginControls();}catch{$('#loginStatus').textContent='Could not load sign-in settings. Refresh to retry.';}}

$('#adminPassword').addEventListener('keydown',e=>{if(e.key==='Enter')$('#loginBtn').click()});
$$('[data-view]').forEach(a=>a.addEventListener('click',e=>{e.preventDefault();view(a.dataset.view)}));
$('#mobileMenu').onclick=()=>$('#sidebar').classList.toggle('open');
$('#drawerBackdrop').onclick=e=>{if(e.target===e.currentTarget)closeDrawer()};$('#modalBackdrop').onclick=e=>{if(e.target===e.currentTarget)closeModal()};
$('#refreshBtn').onclick=()=>{loadAll();toast('Dashboard refreshed')};
$('#globalSearch').addEventListener('input',()=>{renderOrders();renderProducts();renderCustomers()});
$('#orderStatusFilter').onchange=renderOrders;$('#orderPaymentFilter').onchange=renderOrders;$('#productSearch').oninput=renderProducts;$('#customerSearch').oninput=renderCustomers;$('#inventoryFilter').onchange=renderInventory;$('#returnFilter').onchange=renderReturns;$('#auditSearch').oninput=renderAudit;$('#supportFilter').onchange=renderSupport;
$('#overviewDays').onchange=async()=>{const r=await api(`/api/admin/analytics?days=${encodeURIComponent($('#overviewDays').value)}`);if(r.r.ok){cache.analytics=r.j;renderOverviewChart();renderAnalytics()}};
$('#analyticsDays').onchange=async()=>{const r=await api(`/api/admin/analytics?days=${encodeURIComponent($('#analyticsDays').value)}`);if(r.r.ok){cache.analytics=r.j;renderAnalytics()}};
$('#openProductCreate').onclick=()=>productEditor();
$('#createCoupon').onclick=async()=>{const body={code:$('#couponCode').value.trim().toUpperCase(),percentOff:$('#couponPercent').value,fixedOff:$('#couponFixed').value,minimumSubtotal:$('#couponMin').value,maxUses:$('#couponMax').value,expiresAt:$('#couponExpiry').value||null};const r=await api('/api/admin/coupons',{method:'POST',body:JSON.stringify(body)});if(!r.r.ok)return toast(r.j.error||'Could not create coupon');['#couponCode','#couponPercent','#couponFixed','#couponMin','#couponMax','#couponExpiry'].forEach(x=>$(x).value='');toast('Promotion created');loadAll()};
window.addEventListener('hashchange',()=>{const id=location.hash.slice(1)||'overview';if($('#'+id)?.classList.contains('view'))view(id)});

document.addEventListener('click',async event=>{
 const button=event.target.closest('[data-cod-collect]');if(!button)return;
 const receiptReference=prompt('Receipt reference for cash already collected:','');if(!receiptReference?.trim())return;
 const result=await api(`/api/admin/orders/${encodeURIComponent(button.dataset.codCollect)}/confirm-cod`,{method:'POST',body:JSON.stringify({receiptReference})});
 if(!result.r.ok)return toast(result.j.error||'Could not record collection');
 toast('COD collection recorded');closeDrawer();loadAll();
});

// Resume only after the server's admin + MFA guard accepts the current session.
(async()=>{try{const verified=await api('/api/admin/metrics');if(!verified.r.ok){await loadAdminAuthMethod();return;}const token=await api('/api/auth/csrf');if(!token.r.ok)return;csrf=token.j.csrfToken;$('#auth').classList.add('hidden');$('#app').classList.remove('hidden');$('#app').classList.add('show');$('#settingsBase').textContent=location.host;await loadAll();const target=location.hash.slice(1)||'overview';view(document.getElementById(target)?.classList.contains('view')?target:'overview');}catch{toast('Unable to restore your workspace. Please sign in again.');}})();
